// Dithers College on Dithers Hill (new streets only): the campus of the real Mayflower Hill, traced from OpenStreetMap
// into dithersPlan.ts (generated by scratch/campus/tools/gen.mjs; tools/briefs/dithers-campus-plan.json has the real names).
//
// Procedural massing, no models: every building is its footprint rectangles, wall bays that carry a painted brick-and-sash
// cell from one small atlas (windows glow at night), a white cornice, a slate gable or flat roof, and for the landmarks a
// white portico, cupola, the library's clock tower or the chapel's spire. Quad paths, drives, car parks, pitches, the
// track and Johnson Pond are draped on the terrain. All walls, roofs and trim are ONE mesh and all ground cover is one
// more, so the whole campus is two draw calls (plus the pond) and culls as one.
import * as THREE from 'three';
import type { WorldPart } from '../core/api';
import type { Game } from '../core/game';
import type { CityMaterials } from './materials';
import { groundAt } from './plan';
import { loadHeroes, setHeroNight, type HeroSpec } from './dithersHero';
import { buildCampusProps } from './dithersProps';
import { CAMPUS_BUILDINGS, CAMPUS_DRIVES, CAMPUS_FIELDS, CAMPUS_LOTS, CAMPUS_PATHS, CAMPUS_POND, CAMPUS_TRACK } from './dithersPlan';

// ── Atlas of wall cells ──────────────────────────────────────────────────────────────────────────────────────────────────
// One cell is one bay of one storey. Columns: 0 Georgian brick+sash, 1 flat brick ribbon, 2 glass, 3 museum, 4 arena, 5 plant, 6 concrete, 7 door bay,
// 8 tall arched brick window (the chapel), 9 the museum pavilions' glass wall.
const CELL = 128, NCELL = 10;
function atlas(): { map: THREE.CanvasTexture; glow: THREE.CanvasTexture } {
  const mk = (): [HTMLCanvasElement, CanvasRenderingContext2D] => { const c = document.createElement('canvas'); c.width = CELL * NCELL; c.height = CELL; return [c, c.getContext('2d')!]; };
  const [ca, a] = mk(), [cg, g] = mk();
  g.fillStyle = '#000'; g.fillRect(0, 0, ca.width, ca.height);
  let seed = 7; const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
  const brick = (x0: number, base: string, tone = 22): void => {
    a.fillStyle = base; a.fillRect(x0, 0, CELL, CELL);
    for (let r = 0; r < 16; r++) for (let c = -1; c < 8; c++) {
      const bx = x0 + c * 16 + (r & 1 ? 8 : 0), by = r * 8, v = (rnd() - 0.5) * tone;
      a.fillStyle = `rgb(${156 + v},${64 + v * 0.5},${50 + v * 0.4})`; a.fillRect(Math.max(x0, bx + 1), by + 1, Math.min(14, x0 + CELL - bx - 1), 6);
    }
  };
  const glass = (x0: number, y0: number, w: number, h: number, cols: number, rows: number, frame: string, tint = '#26303c'): void => {
    a.fillStyle = frame; a.fillRect(x0 - 3, y0 - 3, w + 6, h + 6);
    a.fillStyle = tint; a.fillRect(x0, y0, w, h);
    g.fillStyle = '#ffd68a'; g.fillRect(x0, y0, w, h);
    a.fillStyle = frame; g.fillStyle = '#000';
    for (let i = 1; i < cols; i++) { a.fillRect(x0 + (w * i) / cols - 1, y0, 2, h); g.fillRect(x0 + (w * i) / cols - 1, y0, 2, h); }
    for (let j = 1; j < rows; j++) { a.fillRect(x0, y0 + (h * j) / rows - 1, w, 2); g.fillRect(x0, y0 + (h * j) / rows - 1, w, 2); }
  };
  // 0: Georgian
  brick(0, '#8f3b2f');
  glass(34, 30, 60, 72, 2, 3, '#f1ede2');
  a.fillStyle = '#f1ede2'; a.fillRect(28, 20, 72, 8); a.fillRect(30, 104, 68, 5); a.fillRect(0, 0, CELL, 4);
  // 1: flat brick, ribbon window
  brick(CELL, '#7f3a2f', 16);
  glass(CELL + 14, 36, 100, 56, 4, 1, '#c9c4b8');
  // 2: glass curtain wall
  a.fillStyle = '#9db3c4'; a.fillRect(2 * CELL, 0, CELL, CELL); glass(2 * CELL + 3, 4, 122, 120, 3, 1, '#59646e', '#3d5468');
  a.fillStyle = '#59646e'; a.fillRect(2 * CELL, 62, CELL, 3);
  // 3: museum, pale stone and big glazing
  a.fillStyle = '#d3cbb8'; a.fillRect(3 * CELL, 0, CELL, CELL);
  for (let i = 0; i < 4; i++) { a.fillStyle = '#c4bba6'; a.fillRect(3 * CELL + i * 32, 0, 1, CELL); }
  glass(3 * CELL + 10, 18, 108, 92, 2, 1, '#e9e3d4', '#34475a');
  // 4: arena, metal ribs and a glazing band
  a.fillStyle = '#8f98a2'; a.fillRect(4 * CELL, 0, CELL, CELL);
  for (let i = 0; i < 16; i++) { a.fillStyle = i & 1 ? '#838c96' : '#9aa3ad'; a.fillRect(4 * CELL + i * 8, 0, 8, CELL); }
  glass(4 * CELL + 6, 78, 116, 24, 4, 1, '#6b747e', '#2c4256');
  // 5: plant, grey block and a small window
  a.fillStyle = '#8d8a82'; a.fillRect(5 * CELL, 0, CELL, CELL);
  for (let r = 0; r < 8; r++) { a.fillStyle = '#7b786f'; a.fillRect(5 * CELL, r * 16, CELL, 1); }
  glass(5 * CELL + 44, 40, 40, 30, 2, 1, '#cfcac0');
  // 6: concrete
  a.fillStyle = '#aaa79d'; a.fillRect(6 * CELL, 0, CELL, CELL);
  for (let i = 0; i < 6; i++) { a.fillStyle = '#9c998f'; a.fillRect(6 * CELL, i * 22, CELL, 2); }
  // 7: door bay on brick with white doorcase
  brick(7 * CELL, '#8f3b2f');
  a.fillStyle = '#f1ede2'; a.fillRect(7 * CELL + 30, 34, 68, 94); a.fillRect(7 * CELL + 24, 26, 80, 8);
  a.fillStyle = '#243a30'; a.fillRect(7 * CELL + 40, 52, 48, 76);
  a.fillStyle = '#26303c'; a.fillRect(7 * CELL + 40, 38, 48, 12); g.fillStyle = '#ffd68a'; g.fillRect(7 * CELL + 40, 38, 48, 12);
  // 8: tall round-headed window in brick (chapel), white surround
  {
    const x0 = 8 * CELL; brick(x0, '#8f3b2f');
    const arch = (cx: number, top: number, bot: number, hw: number, ctx: CanvasRenderingContext2D, col: string): void => { ctx.fillStyle = col; ctx.beginPath(); ctx.moveTo(cx - hw, bot); ctx.lineTo(cx - hw, top + hw); ctx.arc(cx, top + hw, hw, Math.PI, 0); ctx.lineTo(cx + hw, bot); ctx.closePath(); ctx.fill(); };
    arch(x0 + 64, 8, 124, 25, a, '#f1ede2'); arch(x0 + 64, 13, 124, 19, a, '#26303c'); arch(x0 + 64, 13, 124, 19, g, '#ffd68a');
    a.fillStyle = '#f1ede2'; g.fillStyle = '#000';
    for (const [rx, ry, rw, rh] of [[x0 + 63, 13, 2, 111], [x0 + 45, 70, 38, 2], [x0 + 45, 92, 38, 2], [x0 + 45, 48, 38, 2]]) { a.fillRect(rx, ry, rw, rh); g.fillRect(rx, ry, rw, rh); }
    a.fillRect(x0 + 36, 124, 56, 4);
  }
  // 9: museum glass pavilion wall: sky-tinted panes, thin steel mullions, a pale stone sill
  {
    const x0 = 9 * CELL, gr = a.createLinearGradient(0, 0, 0, CELL);
    gr.addColorStop(0, '#a9c6da'); gr.addColorStop(0.5, '#6f93ad'); gr.addColorStop(1, '#3e5a70');
    a.fillStyle = gr; a.fillRect(x0, 0, CELL, CELL);
    a.fillStyle = 'rgba(255,255,255,0.22)'; a.beginPath(); a.moveTo(x0 + 10, 0); a.lineTo(x0 + 46, 0); a.lineTo(x0 + 14, CELL); a.lineTo(x0 - 22, CELL); a.fill();
    a.fillStyle = '#dcd6c6'; a.fillRect(x0, CELL - 10, CELL, 10); a.fillRect(x0, 0, CELL, 4);
    a.fillStyle = '#4a545c'; for (let i = 0; i <= 4; i++) a.fillRect(x0 + i * 32 - (i === 4 ? 2 : 0), 4, 2, CELL - 14);
    a.fillRect(x0, 54, CELL, 2);
    g.fillStyle = '#ffe6b0'; g.fillRect(x0, 6, CELL, CELL - 18); g.fillStyle = '#000'; for (let i = 0; i <= 4; i++) g.fillRect(x0 + i * 32 - (i === 4 ? 2 : 0), 4, 2, CELL - 14); g.fillRect(x0, 54, CELL, 2);
  }
  const mkTex = (c: HTMLCanvasElement, srgb: boolean): THREE.CanvasTexture => {
    const t = new THREE.CanvasTexture(c); t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.anisotropy = 4; t.minFilter = THREE.LinearMipmapLinearFilter; t.generateMipmaps = true; return t;
  };
  return { map: mkTex(ca, true), glow: mkTex(cg, true) };
}

// ── Geometry buffers ─────────────────────────────────────────────────────────────────────────────────────────────────────
const TMP = new THREE.Color();
class Buf {
  p: number[] = []; n: number[] = []; u: number[] = []; c: number[] = [];
  /** A triangle a b c given counter-clockwise from outside; `out` is a direction the face must point towards. */
  tri(a: number[], b: number[], c: number[], col: number, ua = [0, 0], ub = [0, 0], uc = [0, 0], shade = 1, out?: number[]): void {
    let nx = (b[1] - a[1]) * (c[2] - a[2]) - (b[2] - a[2]) * (c[1] - a[1]);
    let ny = (b[2] - a[2]) * (c[0] - a[0]) - (b[0] - a[0]) * (c[2] - a[2]);
    let nz = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    const l = Math.hypot(nx, ny, nz) || 1; nx /= l; ny /= l; nz /= l;
    if (out && nx * out[0] + ny * out[1] + nz * out[2] < 0) { [b, c] = [c, b]; [ub, uc] = [uc, ub]; nx = -nx; ny = -ny; nz = -nz; }
    const lc = TMP.setHex(col), r = lc.r * shade, g = lc.g * shade, bl = lc.b * shade;
    for (const [v, uv] of [[a, ua], [b, ub], [c, uc]] as [number[], number[]][]) { this.p.push(v[0], v[1], v[2]); this.n.push(nx, ny, nz); this.u.push(uv[0], uv[1]); this.c.push(r, g, bl); }
  }
  quad(a: number[], b: number[], c: number[], d: number[], col: number, out?: number[], uv?: number[], shade = 1): void {
    const [u0, v0, u1, v1] = uv ?? [0, 0, 0, 0];
    this.tri(a, b, c, col, [u0, v0], [u1, v0], [u1, v1], shade, out);
    this.tri(a, c, d, col, [u0, v0], [u1, v1], [u0, v1], shade, out);
  }
  mesh(mat: THREE.Material, cast: boolean, receive: boolean): THREE.Mesh | null {
    if (!this.p.length) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.p, 3)); g.setAttribute('normal', new THREE.Float32BufferAttribute(this.n, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.u, 2)); g.setAttribute('color', new THREE.Float32BufferAttribute(this.c, 3));
    g.computeBoundingSphere();
    const m = new THREE.Mesh(g, mat); m.castShadow = cast; m.receiveShadow = receive; m.matrixAutoUpdate = false; m.updateMatrix();
    return m;
  }
}

interface R5 { cx: number; cz: number; w: number; d: number; a: number }
const rotOut = (r: R5): number[] => [-Math.sin(r.a), 0, Math.cos(r.a)];
const rot = (r: R5, lx: number, lz: number): [number, number] => { const c = Math.cos(r.a), s = Math.sin(r.a); return [r.cx + lx * c - lz * s, r.cz + lx * s + lz * c]; };

const WHITE = 0xf1ede2, SLATE = 0x2f353c, BRICK = 0x9a4033, GRANITE = 0xaaa79d, GOLD = 0xc9a24a, CONCRETE = 0xb6b3aa;
// style 0 geo 1 flat 2 glass 3 museum 4 arena 5 plant 6 stand
const FH = [3.6, 3.8, 4.2, 5, 12, 4.2, 3.5], BAY = [3.2, 3.6, 3.4, 6, 6, 4, 4];

class Campus {
  W = new Buf(); F = new Buf(); G = new Buf();
  constructor(private game: Game) {}

  /** Axis-aligned box in a rotated frame: bottom y0, top y1, centre (x,z), half sizes. Faces: sides + top. */
  box(r: R5, lx: number, lz: number, sx: number, sz: number, y0: number, y1: number, col: number, top = true): void {
    const q = (a: number, b: number): number[] => { const [x, z] = rot(r, lx + a * sx / 2, lz + b * sz / 2); return [x, 0, z]; };
    const corners = [q(-1, -1), q(1, -1), q(1, 1), q(-1, 1)];
    for (let i = 0; i < 4; i++) {
      const a = corners[i], b = corners[(i + 1) % 4], mx = (a[0] + b[0]) / 2 - rot(r, lx, lz)[0], mz = (a[2] + b[2]) / 2 - rot(r, lx, lz)[1];
      this.F.quad([a[0], y0, a[2]], [b[0], y0, b[2]], [b[0], y1, b[2]], [a[0], y1, a[2]], col, [mx, 0, mz]);
    }
    if (top) this.F.quad([corners[0][0], y1, corners[0][2]], [corners[1][0], y1, corners[1][2]], [corners[2][0], y1, corners[2][2]], [corners[3][0], y1, corners[3][2]], col, [0, 1, 0]);
  }

  /** Four-sided frustum: half-size h0 at y0 up to h1 at y1 (h1 = 0 for a spire). */
  frustum(r: R5, lx: number, lz: number, y0: number, h0: number, y1: number, h1: number, col: number): void {
    const P = (a: number, b: number, h: number, y: number): number[] => { const [x, z] = rot(r, lx + a * h, lz + b * h); return [x, y, z]; };
    const lo = [P(-1, -1, h0, y0), P(1, -1, h0, y0), P(1, 1, h0, y0), P(-1, 1, h0, y0)], hi = [P(-1, -1, h1, y1), P(1, -1, h1, y1), P(1, 1, h1, y1), P(-1, 1, h1, y1)];
    const c = rot(r, lx, lz);
    for (let i = 0; i < 4; i++) {
      const j = (i + 1) % 4, out = [(lo[i][0] + lo[j][0]) / 2 - c[0], 0.4, (lo[i][2] + lo[j][2]) / 2 - c[1]];
      if (h1 > 0.01) this.F.quad(lo[i], lo[j], hi[j], hi[i], col, out); else this.F.tri(lo[i], lo[j], hi[i], col, [0, 0], [0, 0], [0, 0], 1, out);
    }
  }

  /** Walls of one rectangle: plinth, wall bays by storey (atlas cell `cell`), cornice. */
  walls(r: R5, style: number, floors: number, fh: number, yLow: number, yF: number, shade: number, doors: number[], cellOv = -1): number {
    const bay = BAY[style], cell = style, hw = r.w / 2, hd = r.d / 2;
    const cor: [number, number][] = [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]];
    for (let i = 0; i < 4; i++) {
      const [ax, az] = cor[i], [bx, bz] = cor[(i + 1) % 4], len = Math.hypot(bx - ax, bz - az), nb = Math.max(1, Math.round(len / bay));
      const nx0 = (bz - az) / len, nz0 = -(bx - ax) / len, out = rot(r, nx0, nz0), oc = rot(r, 0, 0), outv = [out[0] - oc[0], 0, out[1] - oc[1]];
      // Outward normal in the local frame (clockwise corners listed counter-clockwise seen from +y: normal = (dz, -dx)).
      const pw = (t: number, y: number): number[] => { const [x, z] = rot(r, ax + ((bx - ax) * t) / nb, az + ((bz - az) * t) / nb); return [x, y, z]; };
      const sideOut = outv;
      // Plinth
      this.F.quad(pw(0, yLow - 0.3), pw(nb, yLow - 0.3), pw(nb, yF + 0.5), pw(0, yF + 0.5), GRANITE, sideOut);
      for (let f = 0; f < floors; f++) for (let k = 0; k < nb; k++) {
        const y0 = yF + 0.5 + f * fh, y1 = y0 + fh;
        const door = f === 0 && style === 0 && doors.includes(i) && k === Math.floor(nb / 2);
        const c = door ? 7 : cellOv >= 0 ? cellOv : cell;
        this.W.quad(pw(k, y0), pw(k + 1, y0), pw(k + 1, y1), pw(k, y1), 0xffffff, sideOut, [c / NCELL + 0.002, 0.995, (c + 1) / NCELL - 0.002, 0.005], shade);
      }
    }
    const yT = yF + 0.5 + floors * fh;
    // White cornice band all round (Georgian) or a pale coping.
    const e = style === 0 ? 0.35 : 0.2, cy = style === 0 ? 0.5 : 0.35;
    const cc = style === 0 ? WHITE : CONCRETE;
    for (let i = 0; i < 4; i++) {
      const [ax, az] = cor[i], [bx, bz] = cor[(i + 1) % 4], len = Math.hypot(bx - ax, bz - az), nx0 = (bz - az) / len, nz0 = -(bx - ax) / len;
      const A = rot(r, ax + nx0 * e, az + nz0 * e), B = rot(r, bx + nx0 * e, bz + nz0 * e), A0 = rot(r, ax, az), B0 = rot(r, bx, bz);
      const oc = rot(r, 0, 0), ov = [rot(r, nx0, nz0)[0] - oc[0], 0, rot(r, nx0, nz0)[1] - oc[1]];
      this.F.quad([A[0], yT - cy, A[1]], [B[0], yT - cy, B[1]], [B[0], yT, B[1]], [A[0], yT, A[1]], cc, ov);
      this.F.quad([A0[0], yT - cy - 0.02, A0[1]], [B0[0], yT - cy - 0.02, B0[1]], [B[0], yT - cy, B[1]], [A[0], yT - cy, A[1]], cc, [0, -1, 0]);
    }
    return yT;
  }

  /** Gable roof along the long axis: slate pitches, brick gable ends, eaves overhang. */
  gable(r: R5, yT: number, rise: number, col = SLATE, endCol = BRICK): void {
    const alongX = r.w >= r.d, o = 0.5, L = (alongX ? r.w : r.d) / 2 + o, Wd = (alongX ? r.d : r.w) / 2 + o;
    const P = (s: number, t: number, y: number): number[] => { const [x, z] = alongX ? rot(r, s, t) : rot(r, t, s); return [x, y, z]; };
    for (const sg of [-1, 1]) {
      this.F.quad(P(-L, sg * Wd, yT - 0.3), P(L, sg * Wd, yT - 0.3), P(L, 0, yT + rise), P(-L, 0, yT + rise), col, (() => { const q = P(0, sg * 10, yT + 4), c = P(0, 0, yT); return [q[0] - c[0], 4, q[2] - c[2]]; })());
      const hw = (alongX ? r.d : r.w) / 2, ls = (alongX ? r.w : r.d) / 2;
      this.F.tri(P(sg * ls, -hw, yT), P(sg * ls, hw, yT), P(sg * ls, 0, yT + rise * 0.96), endCol, [0, 0], [0, 0], [0, 0], 1, (() => { const q = P(sg * 10, 0, yT), c = P(0, 0, yT); return [q[0] - c[0], 0, q[2] - c[2]]; })());
      // chimney stack
    }
    // chimney pair
    const ch = (s: number): void => this.box(r, alongX ? s : 0, alongX ? 0 : s, alongX ? 1.1 : 1.1, 1.1, yT, yT + rise + 1.4, 0x8a3a2d);
    if ((alongX ? r.w : r.d) > 14) { ch(-(alongX ? r.w : r.d) * 0.28); ch((alongX ? r.w : r.d) * 0.28); }
  }

  flatRoof(r: R5, yT: number, col = 0x44474a, over = 0): void {
    const q = (a: number, b: number): number[] => { const [x, z] = rot(r, a * (r.w / 2 + over), b * (r.d / 2 + over)); return [x, yT + 0.05, z]; };
    this.F.quad(q(-1, -1), q(1, -1), q(1, 1), q(-1, 1), col, [0, 1, 0]);
  }

  cupola(r: R5, yR: number): void {
    const b: R5 = { ...r, w: 2.2, d: 2.2 };
    this.box(b, 0, 0, 2.2, 2.2, yR, yR + 1.2, WHITE);
    this.box(b, 0, 0, 1.7, 1.7, yR + 1.2, yR + 3, WHITE);
    for (const sg of [-1, 1]) { this.box(b, sg * 0.86, 0, 0.1, 1.2, yR + 1.5, yR + 2.7, 0x26303c, false); this.box(b, 0, sg * 0.86, 1.2, 0.1, yR + 1.5, yR + 2.7, 0x26303c, false); }
    this.box(b, 0, 0, 2.1, 2.1, yR + 3, yR + 3.25, WHITE);
    this.frustum(b, 0, 0, yR + 3.25, 1.2, yR + 5.4, 0.04, 0x3a4a4a);
    this.box(b, 0, 0, 0.18, 0.18, yR + 5.3, yR + 6, GOLD);
  }

  portico(r: R5, yF: number, floors: number, fh: number): void {
    const z0 = r.d / 2, depth = 3, h = Math.min(floors, 2) * fh, wdt = Math.min(r.w * 0.5, 11);
    this.box(r, 0, z0 + depth / 2, wdt, depth, yF, yF + 0.5, GRANITE);
    const n = 4;
    for (let i = 0; i < n; i++) { const lx = -wdt / 2 + 0.6 + (i * (wdt - 1.2)) / (n - 1); this.box(r, lx, z0 + depth - 0.5, 0.6, 0.6, yF + 0.5, yF + 0.5 + h, WHITE); }
    this.box(r, 0, z0 + depth / 2, wdt + 0.4, depth + 0.3, yF + 0.5 + h, yF + 1.2 + h, WHITE);
    const P = (lx: number, lz: number, y: number): number[] => { const [x, z] = rot(r, lx, lz); return [x, y, z]; };
    const oc = rot(r, 0, 1), c0 = rot(r, 0, 0);
    this.F.tri(P(-wdt / 2, z0 + depth + 0.15, yF + 1.2 + h), P(wdt / 2, z0 + depth + 0.15, yF + 1.2 + h), P(0, z0 + depth + 0.15, yF + 1.2 + h + wdt * 0.17), WHITE, [0, 0], [0, 0], [0, 0], 1, [oc[0] - c0[0], 0, oc[1] - c0[1]]);
    this.F.tri(P(-wdt / 2, z0 + 0.1, yF + 1.2 + h), P(wdt / 2, z0 + 0.1, yF + 1.2 + h), P(0, z0 + 0.1, yF + 1.2 + h + wdt * 0.17), WHITE, [0, 0], [0, 0], [0, 0], 1, [-(oc[0] - c0[0]), 0, -(oc[1] - c0[1])]);
  }

  /** A stepped tower and spire: brick shaft, white stages, tapering spire to `tip`. */
  tower(r: R5, lx: number, lz: number, size: number, y0: number, brickTop: number, tip: number, stages: number): void {
    const h = size / 2;
    this.box(r, lx, lz, size, size, y0, brickTop, BRICK, false);
    for (const [dx, dz, ww, dd] of [[h, 0, 0.1, size], [-h, 0, 0.1, size], [0, h, size, 0.1], [0, -h, size, 0.1]]) void [dx, dz, ww, dd];
    let y = brickTop; const st = (tip - brickTop) * 0.45 / stages;
    this.box(r, lx, lz, size + 0.5, size + 0.5, brickTop, brickTop + 0.35, WHITE);
    y += 0.35;
    for (let i = 0; i < stages; i++) {
      const s = size * (0.86 - i * 0.14);
      this.box(r, lx, lz, s, s, y, y + st, WHITE, false);
      // dark louvre / clock faces
      for (const [ox, oz, bw, bd] of [[s / 2 + 0.03, 0, 0.05, s * 0.5], [-s / 2 - 0.03, 0, 0.05, s * 0.5], [0, s / 2 + 0.03, s * 0.5, 0.05], [0, -s / 2 - 0.03, s * 0.5, 0.05]])
        this.box(r, lx + ox, lz + oz, bw, bd, y + st * 0.25, y + st * 0.8, i === 0 ? 0x26303c : 0x3a3f46, false);
      this.box(r, lx, lz, s + 0.4, s + 0.4, y + st, y + st + 0.3, WHITE);
      y += st + 0.3;
    }
    this.frustum(r, lx, lz, y, size * (0.86 - stages * 0.14 + 0.12), tip - 1.5, 0.05, 0xe9e6dc);
    this.box(r, lx, lz, 0.14, 0.14, tip - 2, tip, GOLD);
  }
}

// ── Terrain drape ────────────────────────────────────────────────────────────────────────────────────────────────────────
const up = [0, 1, 0];
function ribbon(B: Buf, pts: number[], w: number, dy: number, col: number, closed = false): void {
  const P: [number, number][] = [];
  for (let i = 0; i < pts.length; i += 2) P.push([pts[i], pts[i + 1]]);
  if (closed) P.push(P[0]);
  const D: [number, number][] = [];
  for (let i = 0; i < P.length - 1; i++) {
    const n = Math.max(1, Math.ceil(Math.hypot(P[i + 1][0] - P[i][0], P[i + 1][1] - P[i][1]) / 3));
    for (let k = 0; k < n; k++) D.push([P[i][0] + ((P[i + 1][0] - P[i][0]) * k) / n, P[i][1] + ((P[i + 1][1] - P[i][1]) * k) / n]);
  }
  D.push(P[P.length - 1]);
  const L: number[][] = [], Rr: number[][] = [];
  for (let i = 0; i < D.length; i++) {
    const a = D[Math.max(0, i - 1)], b = D[Math.min(D.length - 1, i + 1)];
    let tx = b[0] - a[0], tz = b[1] - a[1]; const l = Math.hypot(tx, tz) || 1; tx /= l; tz /= l;
    const lx = D[i][0] - tz * w / 2, lz = D[i][1] + tx * w / 2, rx = D[i][0] + tz * w / 2, rz = D[i][1] - tx * w / 2;
    L.push([lx, groundAt(lx, lz) + dy, lz]); Rr.push([rx, groundAt(rx, rz) + dy, rz]);
  }
  for (let i = 0; i < D.length - 1; i++) B.quad(L[i], Rr[i], Rr[i + 1], L[i + 1], col, up);
}

function pip(x: number, z: number, p: number[]): boolean {
  let c = false;
  for (let i = 0, j = p.length - 2; i < p.length; j = i, i += 2) { const zi = p[i + 1], zj = p[j + 1]; if ((zi > z) !== (zj > z) && x < ((p[j] - p[i]) * (z - zi)) / (zj - zi) + p[i]) c = !c; }
  return c;
}

/** Flat polygon draped on the terrain: triangulated, then split until no edge is longer than `max`. */
function polygon(B: Buf, p: number[], dy: number, col: number, max = 7, yFix?: number): void {
  const pts: THREE.Vector2[] = [];
  for (let i = 0; i < p.length; i += 2) pts.push(new THREE.Vector2(p[i], p[i + 1]));
  if (pts.length > 2 && pts[0].distanceTo(pts[pts.length - 1]) < 1e-6) pts.pop();
  const tris = THREE.ShapeUtils.triangulateShape(pts, []);
  const Y = (x: number, z: number): number => (yFix !== undefined ? yFix : groundAt(x, z) + dy);
  const emit = (a: number[], b: number[], c: number[], depth: number): void => {
    const ab = Math.hypot(a[0] - b[0], a[1] - b[1]), bc = Math.hypot(b[0] - c[0], b[1] - c[1]), ca = Math.hypot(c[0] - a[0], c[1] - a[1]);
    if (depth < 7 && Math.max(ab, bc, ca) > max) {
      if (ab >= bc && ab >= ca) { const m = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]; emit(a, m, c, depth + 1); emit(m, b, c, depth + 1); }
      else if (bc >= ca) { const m = [(b[0] + c[0]) / 2, (b[1] + c[1]) / 2]; emit(a, b, m, depth + 1); emit(a, m, c, depth + 1); }
      else { const m = [(c[0] + a[0]) / 2, (c[1] + a[1]) / 2]; emit(a, b, m, depth + 1); emit(m, b, c, depth + 1); }
      return;
    }
    B.tri([a[0], Y(a[0], a[1]), a[1]], [b[0], Y(b[0], b[1]), b[1]], [c[0], Y(c[0], c[1]), c[1]], col, [0, 0], [0, 0], [0, 0], 1, up);
  };
  for (const t of tris) emit([pts[t[0]].x, pts[t[0]].y], [pts[t[1]].x, pts[t[1]].y], [pts[t[2]].x, pts[t[2]].y], 0);
}

/** Rotated rectangle as a draped grid of `cell`-metre squares; colour from f(i,j). */
function gridRect(B: Buf, cx: number, cz: number, w: number, d: number, a: number, dy: number, cell: number, f: (i: number, j: number) => number): void {
  const nx = Math.max(1, Math.ceil(w / cell)), nz = Math.max(1, Math.ceil(d / cell)), c = Math.cos(a), s = Math.sin(a);
  const V = (i: number, j: number): number[] => { const lx = -w / 2 + (w * i) / nx, lz = -d / 2 + (d * j) / nz, x = cx + lx * c - lz * s, z = cz + lx * s + lz * c; return [x, groundAt(x, z) + dy, z]; };
  for (let i = 0; i < nx; i++) for (let j = 0; j < nz; j++) B.quad(V(i, j), V(i + 1, j), V(i + 1, j + 1), V(i, j + 1), f(i, j), up);
}

function outline(B: Buf, cx: number, cz: number, w: number, d: number, a: number, dy: number, col: number, lw = 0.16): void {
  const c = Math.cos(a), s = Math.sin(a), pts: number[] = [];
  for (const [i, j] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) pts.push(cx + (i * w / 2) * c - (j * d / 2) * s, cz + (i * w / 2) * s + (j * d / 2) * c);
  ribbon(B, pts, lw, dy, col, true);
}

/** Boxes round a rotated rectangle for collision: one for a near-axis rectangle, a staircase of boxes otherwise. */
function collide(game: Game, r: R5, top: number, base: number): void {
  const a = ((r.a % Math.PI) + Math.PI) % Math.PI, q = Math.min(a, Math.abs(Math.PI - a), Math.abs(a - Math.PI / 2));
  const c = Math.abs(Math.cos(r.a)), s = Math.abs(Math.sin(r.a));
  if (q < 0.1) { const hx = (r.w * c + r.d * s) / 2, hz = (r.w * s + r.d * c) / 2; game.col.addBox(r.cx - hx, r.cz - hz, r.cx + hx, r.cz + hz, top, base); return; }
  const long = r.w >= r.d, L = long ? r.w : r.d, Sd = long ? r.d : r.w, n = Math.max(2, Math.ceil(L / Math.max(2, Sd * 0.6))), seg = L / n;
  for (let i = 0; i < n; i++) {
    const t = -L / 2 + seg * (i + 0.5), [x, z] = long ? rot(r, t, 0) : rot(r, 0, t);
    const hx = (seg * (long ? c : s) + Sd * (long ? s : c)) / 2, hz = (seg * (long ? s : c) + Sd * (long ? c : s)) / 2;
    game.col.addBox(x - hx, z - hz, x + hx, z + hz, top, base);
  }
}

export function buildDithersCampus(game: Game, mats: CityMaterials, parent: THREE.Object3D): WorldPart {
  const C = new Campus(game), grp = new THREE.Group();
  grp.name = 'dithers-campus'; parent.add(grp);
  const tex = atlas();
  const wallMat = (mats.facade[1].clone() as THREE.MeshStandardMaterial);
  wallMat.map = tex.map; wallMat.emissiveMap = tex.glow; wallMat.vertexColors = true; wallMat.roughnessMap = null; wallMat.metalnessMap = null; wallMat.normalMap = null;
  wallMat.roughness = 0.85; wallMat.metalness = 0;
  const solidMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.8, metalness: 0 });
  const groundMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.92, metalness: 0, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  const env = (mats.flat as THREE.MeshStandardMaterial).envMap ?? null;
  wallMat.envMap = env; solidMat.envMap = env; solidMat.envMapIntensity = 0.5;

  // ── Ground cover first (it sits under the buildings) ──
  for (const lot of CAMPUS_LOTS) { polygon(C.G, lot, 0.07, 0x4b4c4e); }
  for (const dr of CAMPUS_DRIVES) ribbon(C.G, dr, 5.2, 0.08, 0x4b4c4e);
  for (const p of CAMPUS_PATHS) ribbon(C.G, p, 2.2, 0.1, 0x9c6f58);
  const grass = [0x5f9a47, 0x6aa650];
  for (const [sport, cx, cz, w, d, a] of CAMPUS_FIELDS) {
    if (sport === 5) {
      gridRect(C.G, cx, cz, w, d, a, 0.06, 6, () => 0x3f7a62);
      for (let i = 0; i < 3; i++) for (let j = 0; j < 2; j++) {
        const cw = w / 3 - 1.2, cd = d / 2 - 1.2, [x, z] = rot({ cx, cz, w, d, a }, -w / 2 + (i + 0.5) * (w / 3), -d / 2 + (j + 0.5) * (d / 2));
        outline(C.G, x, z, cw, cd, a, 0.12, 0xf2f0e6, 0.12); gridRect(C.G, x, z, cw, cd, a, 0.09, 6, () => 0x4d8fa8);
        outline(C.G, x, z, cw, cd, a, 0.14, 0xf2f0e6, 0.12);
      }
      continue;
    }
    gridRect(C.G, cx, cz, w, d, a, 0.06, 5, (i) => grass[i & 1]);
    outline(C.G, cx, cz, w - 1, d - 1, a, 0.12, 0xf2f0e6, 0.18);
    if (sport === 2 || sport === 3) { const [hx, hz] = rot({ cx, cz, w, d, a }, -w * 0.3, 0); gridRect(C.G, hx, hz, 12, 12, a + Math.PI / 4, 0.1, 4, () => 0xa8794e); }
    else { ribbon(C.G, [...rot({ cx, cz, w, d, a }, 0, -d / 2 + 0.5), ...rot({ cx, cz, w, d, a }, 0, d / 2 - 0.5)], 0.14, 0.13, 0xf2f0e6); }
  }
  {
    const T = CAMPUS_TRACK, c = Math.cos(T.a), s = Math.sin(T.a), loop = (r: number): number[] => {
      const pts: number[] = [];
      for (let i = 0; i < 48; i++) { const side = i < 24 ? 1 : -1, k = ((i % 24) / 23) * Math.PI, u = side * (T.straight / 2 + Math.sin(k) * r), v = -side * Math.cos(k) * r; pts.push(T.cx + u * c - v * s, T.cz + u * s + v * c); }
      return pts;
    };
    polygon(C.G, [...loop(T.r_in - 0.5), ...loop(T.r_in - 0.5).slice(0, 2)], 0.05, 0x6aa650, 6);
    const mid = T.r_in + (T.lanes * T.lane_w) / 2;
    ribbon(C.G, loop(mid), T.lanes * T.lane_w + 0.3, 0.1, 0xb4523c, true);
    for (let k = 0; k <= T.lanes; k++) ribbon(C.G, loop(T.r_in + k * T.lane_w), 0.1, 0.14, 0xf2f0e6, true);
  }

  // ── Buildings ──
  const sizeOf = (st: number, fl: number): number => (st === 4 ? 12 : st === 6 ? 3.5 : fl * FH[st] + 0.5);
  const standIns: THREE.Mesh[] = [], heroes: HeroSpec[] = [];
  let seed = 11; const rnd = (): number => ((seed = (seed * 16807) % 2147483647) / 2147483647);
  for (const [style, floors, flags, , rects] of CAMPUS_BUILDINGS) {
    const R: R5[] = [];
    for (let i = 0; i + 4 < rects.length; i += 5) R.push({ cx: rects[i], cz: rects[i + 1], w: rects[i + 2], d: rects[i + 3], a: rects[i + 4] });
    if (!R.length) continue;
    const shade = 0.9 + rnd() * 0.18;
    let yTop0 = 0;
    // The library and the chapel are Blender models (dithersHero.ts); the code-built massing stands in until they load.
    const hero = flags & 3 ? { W: C.W, F: C.F, yF: -1e9 } : null;
    if (hero) { C.W = new Buf(); C.F = new Buf(); }
    for (let ri = 0; ri < R.length; ri++) {
      const r = R[ri];
      let yHi = -1e9, yLo = 1e9;
      for (let i = 0; i < 9; i++) { const [x, z] = rot(r, ((i % 3) - 1) * r.w / 2, (Math.floor(i / 3) - 1) * r.d / 2); const g = groundAt(x, z); yHi = Math.max(yHi, g); yLo = Math.min(yLo, g); }
      if (style === 6) {
        // grandstand: a wedge of seating under a canopy
        const h = 3.4, P = (lx: number, lz: number, y: number): number[] => { const [x, z] = rot(r, lx, lz); return [x, y, z]; };
        C.box(r, 0, 0, r.w, r.d, yLo - 0.5, yHi + 1.2, CONCRETE, false);
        C.F.quad(P(-r.w / 2, -r.d / 2, yHi + 1.2), P(r.w / 2, -r.d / 2, yHi + 1.2), P(r.w / 2, r.d / 2, yHi + 1.2 + h), P(-r.w / 2, r.d / 2, yHi + 1.2 + h), 0x8d8f93, [0, 1, 0]);
        C.F.quad(P(-r.w / 2, r.d / 2, yHi + 1.2), P(r.w / 2, r.d / 2, yHi + 1.2), P(r.w / 2, r.d / 2, yHi + 1.2 + h), P(-r.w / 2, r.d / 2, yHi + 1.2 + h), CONCRETE, rotOut(r));
        C.box(r, 0, r.d / 2 - 0.2, r.w + 0.4, 0.4, yHi + 1.2 + h, yHi + 1.4 + h, 0x6d747b);
        collide(game, r, yHi + 1.2 + h, yLo - 1);
        continue;
      }
      const h = (flags & 2) && ri === 0 ? 9.5 : FH[style];
      const fl = (flags & 2) && ri === 0 ? 1 : style === 4 ? 1 : floors;
      const yF = yHi + 0.2, yT = C.walls(r, style, fl, h, yLo, yF, shade, ri === 0 && (flags & 8) ? [3] : [], (flags & 2) ? 8 : style === 3 && ri > 0 ? 9 : -1);
      if (hero && ri === 0) hero.yF = yF;
      if (ri === 0) yTop0 = yT;
      const lowRise = Math.min(r.w, r.d) < 3.2;
      if (style === 0 && !lowRise) C.gable(r, yT, Math.max(2, Math.min(r.w, r.d) * 0.3));
      else if (style === 4) C.gable(r, yT, 2.2, 0x7d8890, 0x8f98a2);
      else C.flatRoof(r, yT, style === 3 ? 0xcfc8b8 : 0x44474a, 0.2);
      collide(game, r, yT + 3, yLo - 1);
      if (ri === 0) {
        const ridge = yT + (style === 0 && !lowRise ? Math.max(2, Math.min(r.w, r.d) * 0.3) : 0);
        if (flags & 8) C.portico(r, yF, fl, h);
        if (flags & 4) C.cupola(r, ridge);
        if (flags & 1) C.tower(r, 0, -r.d * 0.05, 6, ridge - 2, ridge + 10, 52 + (yF - 12), 3);
        if (flags & 2) C.tower(r, -r.w / 2 + 2.4, 0, 4.2, yF, yT + 6, 38 + (yF - 12), 2);
      }
    }
    void yTop0; void sizeOf;
    if (hero) {
      for (const m of [C.W.mesh(wallMat, true, true), C.F.mesh(solidMat, true, true)]) if (m) { standIns.push(m); grp.add(m); }
      C.W = hero.W; C.F = hero.F;
      const r0 = R[0], c0 = Math.cos(r0.a), s0 = Math.sin(r0.a);
      heroes.push(flags & 1 ? { name: 'library', x: r0.cx, y: hero.yF, z: r0.cz, yaw: -r0.a } : { name: 'chapel', x: r0.cx, y: hero.yF, z: r0.cz, yaw: Math.atan2(-c0, -s0) });
    }
  }

  // ── Johnson Pond: a still sheet at the mean of its bank, with a dark bank skirt where the hill falls away ──
  const pond = CAMPUS_POND; let sum = 0, n = 0, hi = -1e9;
  for (let i = 0; i < pond.length; i += 2) { const g = groundAt(pond[i], pond[i + 1]); sum += g; n++; hi = Math.max(hi, g); }
  let pcx = 0, pcz = 0;
  for (let i = 0; i < pond.length; i += 2) { pcx += pond[i] / (pond.length / 2); pcz += pond[i + 1] / (pond.length / 2); }
  const hs: number[] = [];
  for (let i = 0; i < pond.length; i += 2) hs.push(groundAt(pond[i], pond[i + 1]));
  hs.sort((a, b) => a - b);
  const pondY = hs[Math.floor(hs.length * 0.8)] - 0.05; void hi; void sum; void n;
  const water = new Buf();
  polygon(water, pond, 0, 0x447689, 9, pondY);
  for (let i = 0; i < pond.length; i += 2) {
    const j = (i + 2) % pond.length, ay = groundAt(pond[i], pond[i + 1]), by = groundAt(pond[j], pond[j + 1]);
    if (ay > pondY + 0.05 && by > pondY + 0.05) continue;
    const top = pondY + 0.02;
    C.F.quad([pond[i], Math.min(ay, top) - 0.2, pond[i + 1]], [pond[j], Math.min(by, top) - 0.2, pond[j + 1]], [pond[j], top, pond[j + 1]], [pond[i], top, pond[i + 1]], 0x5a4a38, [pond[i] - pcx, 0, pond[i + 1] - pcz]);
  }
  const waterMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.12, metalness: 0.0, envMap: env, envMapIntensity: 0.9, polygonOffset: true, polygonOffsetFactor: -1, polygonOffsetUnits: -1 });

  const meshes = [C.W.mesh(wallMat, true, true), C.F.mesh(solidMat, true, true), C.G.mesh(groundMat, false, true), water.mesh(waterMat, false, true)];
  for (const m of meshes) if (m) grp.add(m);
  game.col.allBoxes.length;
  void pip;
  const envNow = (): THREE.Texture | null => (mats.flat as THREE.MeshStandardMaterial).envMap ?? null;
  const props = buildCampusProps(game, grp, envNow());
  loadHeroes(game, grp, heroes, envNow).then((ok) => {
    if (!ok) return;
    for (const m of standIns) { grp.remove(m); m.geometry.dispose(); }
    standIns.length = 0;
  }).catch(() => { /* the code-built massing stays */ });

  return {
    setNight(n: number): void { wallMat.emissiveIntensity = mats.facade[1].emissiveIntensity; setHeroNight(n); props.setNight(n); },
    update(): void { const e = (mats.flat as THREE.MeshStandardMaterial).envMap ?? null; if (wallMat.envMap !== e) { wallMat.envMap = e; solidMat.envMap = e; waterMat.envMap = e; } },
  };
}
